// generated by `bun run shaders`

export const glyph_frag = `\
float atlas_sample(highp sampler2D atlas, ivec2 origin, ivec2 size, vec2 position) {
	vec2 texel = clamp(position - 0.5, vec2(0.0), vec2(size - 1));
	ivec2 first = ivec2(texel);
	ivec2 last = min(first + 1, size - 1);
	vec2 weight = fract(texel);
	float top = mix(
		texelFetch(atlas, origin + first, 0).r,
		texelFetch(atlas, origin + ivec2(last.x, first.y), 0).r,
		weight.x
	);
	float bottom = mix(
		texelFetch(atlas, origin + ivec2(first.x, last.y), 0).r,
		texelFetch(atlas, origin + last, 0).r,
		weight.x
	);
	return mix(top, bottom, weight.y);
}

float atlas_glyph_value(
	highp sampler2D atlas,
	ivec2 glyph_coord,
	vec2 cell_coord,
	vec2 cell_footprint
) {
	ivec2 size = textureSize(atlas, 0) / ivec2(32, 8);

	if (any(lessThan(size, ivec2(1)))) {
		return 0.0;
	}

	ivec2 origin = glyph_coord * size;
	vec2 center = cell_coord * vec2(size);
	vec2 footprint = cell_footprint * vec2(size);

	// Bound the sampling cost for large atlases while spreading taps over the pixel.
	ivec2 taps = ivec2(clamp(ceil(footprint), vec2(1.0), vec2(4.0)));
	vec2 step_size = footprint / vec2(taps);
	vec2 start = center - 0.5 * footprint;
	float coverage = 0.0;

	for (int y = 0; y < taps.y; y++) {

		for (int x = 0; x < taps.x; x++) {
			vec2 position = start + (vec2(x, y) + 0.5) * step_size;
			coverage += atlas_sample(atlas, origin, size, position);
		}

	}

	return coverage / float(taps.x * taps.y);
}

float bitmap_glyph_value(
	mediump usampler2D bitmap,
	ivec2 glyph_coord,
	vec2 cell_coord
) {
	ivec2 pixel = clamp(ivec2(cell_coord * vec2(8.0, 16.0)), ivec2(0), ivec2(7, 15));
	ivec2 packed_coord = ivec2(glyph_coord.x, glyph_coord.y * 4 + pixel.y / 4);
	uvec4 rows = texelFetch(bitmap, packed_coord, 0);
	return float((rows[pixel.y % 4] >> (7 - pixel.x)) & 1u);
}
`;

export const terminal_vert = `\
#version 300 es

in uint a_cell;

uniform int u_rows;
uniform int u_cols;
uniform vec3 u_palette[18];

out vec2 v_cell_coord;

flat out vec3 f_fg_colour;
flat out vec3 f_bg_colour;
flat out ivec2 f_glyph_coord;
flat out uint f_char_code;

void main() {
	int row = gl_InstanceID / u_cols;
	int col = gl_InstanceID % u_cols;

	if (a_cell == 0u) {
		// clipped: don't cover any pixels below this glyph
		// e.g., a previously rendered texture
		gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
		return;
	}

	uint char_code = a_cell & 0xffu;
	uint bg_idx = (a_cell >> 8u) & 0xffu;
	uint fg_idx = (a_cell >> 16u) & 0xffu;

	f_fg_colour = u_palette[fg_idx < 18u ? fg_idx : 16u];
	f_bg_colour = u_palette[bg_idx < 18u ? bg_idx : 17u];

	// 32 glyph columns, 8 glyph rows.
	f_glyph_coord = ivec2(int(char_code % 32u), int(char_code / 32u));
	f_char_code = char_code;

	/* A glyph is made up of two triangles, six vertices:
	 *
	 *   0--2     ,5     0--2,5
	 *   | /  +  / |  =  |   |
	 *   1'     3--4    1,3--4
	 */

	int row_inc = int(gl_VertexID == 1 || gl_VertexID == 3 ||
			  gl_VertexID == 4);

	int col_inc = int(gl_VertexID == 2 || gl_VertexID == 4 ||
			  gl_VertexID == 5);

	v_cell_coord = vec2(float(col_inc), float(row_inc));

	row += row_inc;
	col += col_inc;

	float ndc_x = 2.0 * float(col) / float(u_cols) - 1.0;
	float ndc_y = -2.0 * float(row) / float(u_rows) + 1.0;

	gl_Position = vec4(ndc_x, ndc_y, 0.0, 1.0);
}
`;

export const terminal_frag = `\
#version 300 es

precision highp float;
precision highp int;

${glyph_frag}

in vec2 v_cell_coord;

flat in vec3 f_fg_colour;
flat in vec3 f_bg_colour;
flat in ivec2 f_glyph_coord;
flat in uint f_char_code;

uniform mediump usampler2D u_bitmap_font;
uniform highp sampler2D u_user_font;
uniform bool u_use_user_font;

out vec4 frag_colour;

void main() {
	vec2 cell_footprint = fwidth(v_cell_coord);

	// Codes 176 through 223 use the built-in font.
	if (u_use_user_font && (f_char_code < 176U || f_char_code >= 224U)) {
		float value = atlas_glyph_value(
			u_user_font, f_glyph_coord, v_cell_coord, cell_footprint
		);
		frag_colour = vec4(mix(f_bg_colour, f_fg_colour, value), 1.0);
		return;
	}

	float value = bitmap_glyph_value(u_bitmap_font, f_glyph_coord,
					 v_cell_coord);
	frag_colour = vec4(mix(f_bg_colour, f_fg_colour, value), 1.0);
}
`;
